// Noto Sans Arabic font files (OFL) as base64, embedded for pdfmake's VFS.
// Loaded via dynamic import only when a PDF is generated.
// Noto Sans Arabic ships FULL Arabic Presentation-Forms coverage in its cmap
// (140/141; only U+FE75 tatweel-form is absent, never emitted by the
// reshaper), so reshaped text maps 1:1 to real glyphs without any OpenType
// GSUB pass (pdfmake 0.3 does not shape). Full v2.013 build — includes Latin,
// Western + Arabic-Indic digits and punctuation used across the document.
export const NOTO_SANS_REGULAR_B64 = "";

export const NOTO_SANS_BOLD_B64 = "";
